#include <vector>
#include <iostream>

void push_and_invalidate(std::vector<int>& v) {
    if (v.empty()) return;
    int& first_ref = v.front();

    // Force reallocation (assuming typical growth factor)
    size_t cap = v.capacity();
    while (v.size() <= cap) {
        v.push_back(v.size());
    }

    // first_ref now points to deallocated memory (UB)
    // std::cout << first_ref; // DANGER!
}

int main() {
    std::vector<int> v = {1, 2, 3};
    v.reserve(3); // Capacity = 3
    push_and_invalidate(v);
    // v is now larger and entirely reallocated
}
